import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul(torch::Tensor A, torch::Tensor B);
"""

matmul_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Tiled GEMM: C = A * B, all row-major [N, N] float32
// Each CTA computes a 128x128 tile of C with 256 threads,
// staging 128x8 A-tiles and 8x128 B-tiles in shared memory.
// Optimization: two-stage cp.async software pipeline that overlaps the
// asynchronous global->shared copies of tile k+1 with compute of tile k.
__device__ __forceinline__ void cp_async_16(void* smem_dst, void const* gmem_src) {
#if __CUDA_ARCH__ >= 800
  unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(dst), "l"(gmem_src));
#else
  *reinterpret_cast<float4*>(smem_dst) = *reinterpret_cast<float4 const*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async_4(void* smem_dst, void const* gmem_src) {
#if __CUDA_ARCH__ >= 800
  unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4;\n" :: "r"(dst), "l"(gmem_src));
#else
  *reinterpret_cast<float*>(smem_dst) = *reinterpret_cast<float const*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async_commit_group() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.commit_group;\n" ::);
#endif
}
template <int W>
__device__ __forceinline__ void cp_async_wait_group() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.wait_group %0;\n" :: "n"(W));
#endif
}
__global__ static void matmul_kernel(
    int M, int N, int K,
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 8;
  // Global tensor (row-major)
  Tensor mC = make_tensor(make_gmem_ptr(C),
                          make_shape(M, N),
                          make_stride(N, Int<1>{}));   // (M,N)
  // CTA tiling
  auto cta_tiler = make_shape(Int<BM>{}, Int<BN>{}, Int<BK>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,  X>{});  // (128,128)
  // Double-buffered shared memory
  __shared__ float smemA[2][BM * BK];
  __shared__ float smemB[2][BK * BN];
  int const tid  = threadIdx.x;
  int const m0   = blockIdx.x * BM;
  int const n0   = blockIdx.y * BN;
  int const kmax = K / BK;
  // Stage one (BM x BK) A-tile and one (BK x BN) B-tile into shared
  // memory using asynchronous global->shared copies.
  auto load_tile = [&](int k_tile, int stage) {
    // A tile: rows of 8 contiguous floats; 2 threads per row, 4B copies.
    {
      int const row = tid >> 1;        // 0..127
      int const kh  = (tid & 1) * 4;   // 0 or 4
      float const* src = A + (long)(m0 + row) * K + (long)k_tile * BK + kh;
      float*       dst = smemA[stage] + row + kh * BM;
      cp_async_4(dst + 0 * BM, src + 0);
      cp_async_4(dst + 1 * BM, src + 1);
      cp_async_4(dst + 2 * BM, src + 2);
      cp_async_4(dst + 3 * BM, src + 3);
    }
    // B tile: rows of 128 contiguous floats; one float4 per thread.
    {
      int const kr = tid >> 5;         // 0..7
      int const nc = (tid & 31) * 4;   // 0..124
      float const* src = B + (long)(k_tile * BK + kr) * N + n0 + nc;
      float*       dst = smemB[stage] + kr * BN + nc;
      cp_async_16(dst, src);
    }
  };
  // Thread layout for compute: 16x16 threads, each handles 8x8 outputs
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tCgC = local_partition(gC, tC, tid, Step<_1,_1>{});  // (8,8)
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Prologue: issue the asynchronous loads for the first k-tile
  if (kmax > 0) {
    load_tile(0, 0);
  }
  cp_async_commit_group();
  for (int k_tile = 0; k_tile < kmax; ++k_tile) {
    int const cur = k_tile & 1;
    // Prefetch the next k-tile into the other shared-memory buffer
    if (k_tile + 1 < kmax) {
      load_tile(k_tile + 1, cur ^ 1);
    }
    cp_async_commit_group();
    cp_async_wait_group<1>();  // wait until the current stage has landed
    __syncthreads();
    // Shared-memory tensors for this pipeline stage
    Tensor sA = make_tensor(make_smem_ptr(smemA[cur]),
                            make_layout(make_shape(Int<BM>{}, Int<BK>{}),
                                        make_stride(Int<1>{}, Int<BM>{}))); // (m,k)
    Tensor sB = make_tensor(make_smem_ptr(smemB[cur]),
                            make_layout(make_shape(Int<BN>{}, Int<BK>{}),
                                        make_stride(Int<1>{}, Int<BN>{}))); // (n,k)
    Tensor tCsA = local_partition(sA, tC, tid, Step<_1,  X>{}); // (8,8k)
    Tensor tCsB = local_partition(sB, tC, tid, Step<  X,_1>{}); // (8,8k)
    // Compute rank-k updates from shared memory
    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }
  // Epilogue: write accumulators to global memory
  copy(tCrC, tCgC);
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");

  int64_t M = A.size(0);
  int64_t K = A.size(1);
  int64_t N = B.size(1);
  TORCH_CHECK(B.size(0) == K, "Inner dimensions must match");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 8 == 0,
              "Dimensions must be multiples of the tile sizes (M,N % 128, K % 8)");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::empty({M, N}, A.options());

  dim3 block(256);
  dim3 grid((unsigned)(M / 128), (unsigned)(N / 128));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matmul_kernel<<<grid, block, 0, stream>>>(
      (int)M, (int)N, (int)K,
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>());

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE matmul launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=matmul_cpp_decl,
    cuda_sources=matmul_cuda_src,
    functions=["matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--expt-relaxed-constexpr"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom tiled CUTE/CUDA GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matmul(A, B)

